import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse(`{"title":"Teachable Static Analysis Guide","description":"A practical, user-readable guide to understanding and using Frensense's teachable static analysis system.","frontmatter":{"title":"Teachable Static Analysis Guide","description":"A practical, user-readable guide to understanding and using Frensense's teachable static analysis system."},"headers":[],"relativePath":"guide/teachability.md","filePath":"guide/teachability.md"}`),i={name:"guide/teachability.md"};function r(o,e,l,c,d,h){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="teachable-static-analysis" tabindex="-1">Teachable Static Analysis <a class="header-anchor" href="#teachable-static-analysis" aria-label="Permalink to &quot;Teachable Static Analysis&quot;">​</a></h1><p>Traditional static analysis tools are built like rigid factories: to detect a new vulnerability pattern, someone has to rewrite the machine&#39;s internal gears or learn a specialized, obscure query language.</p><p>Frensense works differently. It was built with a clear separation between <strong>how code is analyzed</strong> and <strong>what vulnerabilities look like</strong>:</p><ol><li><strong>The Engine</strong> (<code>frensense-engine</code>): A compiler that parses code into an Intermediate Representation (IR), tracks how values move between variables, inspects branch conditions, and determines data reachability.</li><li><strong>The Knowledge Bundles</strong> (<code>.frc</code> files): Portable, compiled bundles of security facts that tell the engine which functions are dangerous, which are safe, and what policies must be followed.</li></ol><p>Because of this separation, <strong>you do not need to write Rust, understand compiler theory, or recompile the engine</strong> to teach Frensense new vulnerabilities.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;Vulnerable Example\\n(*_positive)&quot;] --&gt; C[&quot;Frensense Bundler\\n(Fact Extraction)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B[&quot;Remediated Example\\n(*_negative)&quot;] --&gt; C</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;Replay Verification\\n(Gate: 0 False Positives)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[&quot;Compiled Knowledge Bundle\\n(*.frc)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F[&quot;Frensense Scanner\\n(--corpus-bundle)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G[&quot;Target Codebase&quot;] --&gt; F</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; H[&quot;Accurate Findings\\n(Exact Source-to-Sink Path)&quot;]</span></span></code></pre></div><hr><h2 id="the-twin-example-method-how-frensense-learns" tabindex="-1">The Twin-Example Method: How Frensense Learns <a class="header-anchor" href="#the-twin-example-method-how-frensense-learns" aria-label="Permalink to &quot;The Twin-Example Method: How Frensense Learns&quot;">​</a></h2><p>To teach Frensense, you create a <strong>family</strong> consisting of two files:</p><ul><li><strong><code>[name]_positive.[ext]</code></strong>: The vulnerable code containing the dangerous pattern.</li><li><strong><code>[name]_negative.[ext]</code></strong>: The safe version showing how the vulnerability was remediated.</li></ul><h3 id="why-twin-examples-work" tabindex="-1">Why Twin Examples Work <a class="header-anchor" href="#why-twin-examples-work" aria-label="Permalink to &quot;Why Twin Examples Work&quot;">​</a></h3><p>When a security vulnerability occurs in production, an engineer writes a pull request to fix it. That pull request contains the exact difference between &quot;dangerous&quot; and &quot;safe&quot;:</p><ul><li>Did they add an input validation check?</li><li>Did they switch from raw string concatenation to a parameterized query?</li><li>Did they invoke an authorization check before deleting a record?</li></ul><p>The Frensense bundler automatically compares the positive and negative files, identifies what made the difference, and distills it into a <strong>Learned Fact</strong>.</p><hr><h2 id="the-13-teachable-subsystems" tabindex="-1">The 13 Teachable Subsystems <a class="header-anchor" href="#the-13-teachable-subsystems" aria-label="Permalink to &quot;The 13 Teachable Subsystems&quot;">​</a></h2><p>Under the hood, Frensense&#39;s knowledge system is categorized into 13 distinct security dimensions. Every dimension corresponds to an entry in the engine&#39;s <code>LearnedFactEntry</code> table:</p><h3 id="_1-dangerous-sinks-learnedfactentry-sink" tabindex="-1">1. Dangerous Sinks (<code>LearnedFactEntry::Sink</code>) <a class="header-anchor" href="#_1-dangerous-sinks-learnedfactentry-sink" aria-label="Permalink to &quot;1. Dangerous Sinks (`LearnedFactEntry::Sink`)&quot;">​</a></h3><p>A &quot;sink&quot; is a function where untrusted data causes harm (such as executing a system command or running a database query).</p><ul><li><strong>What is taught</strong>: Which argument slot is dangerous.</li><li><strong>Real-world benefit</strong>: In <code>cursor.execute(sql, params)</code>, slot 0 (<code>sql</code>) is dangerous, but slot 1 (<code>params</code>) is a safe parameterized binding channel. The engine learns not to flag parameterized queries.</li></ul><h3 id="_2-untrusted-sources-learnedfactentry-source" tabindex="-1">2. Untrusted Sources (<code>LearnedFactEntry::Source</code>) <a class="header-anchor" href="#_2-untrusted-sources-learnedfactentry-source" aria-label="Permalink to &quot;2. Untrusted Sources (`LearnedFactEntry::Source`)&quot;">​</a></h3><p>A &quot;source&quot; is any place where untrusted user data enters your application.</p><ul><li><strong>What is taught</strong>: Function calls or object properties that deliver user data (e.g., <code>request.cookies.get</code>, <code>request.body.json</code>, or custom RPC gateways).</li></ul><h3 id="_3-sanitizers-learnedfactentry-sanitizer" tabindex="-1">3. Sanitizers (<code>LearnedFactEntry::Sanitizer</code>) <a class="header-anchor" href="#_3-sanitizers-learnedfactentry-sanitizer" aria-label="Permalink to &quot;3. Sanitizers (`LearnedFactEntry::Sanitizer`)&quot;">​</a></h3><p>A &quot;sanitizer&quot; is a function that cleanses data or renders it harmless.</p><ul><li><strong>What is taught</strong>: Escaping helpers (e.g. <code>html.escape()</code>, <code>quote_plus()</code>) or type coercions (<code>int()</code>, <code>float()</code>) that remove risk.</li></ul><h3 id="_4-data-propagators-learnedfactentry-propagator" tabindex="-1">4. Data Propagators (<code>LearnedFactEntry::Propagator</code>) <a class="header-anchor" href="#_4-data-propagators-learnedfactentry-propagator" aria-label="Permalink to &quot;4. Data Propagators (`LearnedFactEntry::Propagator`)&quot;">​</a></h3><p>A &quot;propagator&quot; transforms data while preserving its untrusted nature.</p><ul><li><strong>What is taught</strong>: Encoding/decoding helpers like <code>base64.b64decode</code>, string formatters, or array manipulation functions.</li></ul><h3 id="_5-security-policies-learnedfactentry-policy" tabindex="-1">5. Security Policies (<code>LearnedFactEntry::Policy</code>) <a class="header-anchor" href="#_5-security-policies-learnedfactentry-policy" aria-label="Permalink to &quot;5. Security Policies (`LearnedFactEntry::Policy`)&quot;">​</a></h3><p>Policies enforce that certain security checks must happen in the same function or module as a sensitive operation.</p><ul><li><strong>What is taught</strong>: &quot;Whenever function <code>delete_user()</code> is called, function <code>verify_admin_role()</code> must precede it.&quot;</li></ul><h3 id="_6-non-dataflow-checks-learnedfactentry-check" tabindex="-1">6. Non-Dataflow Checks (<code>LearnedFactEntry::Check</code>) <a class="header-anchor" href="#_6-non-dataflow-checks-learnedfactentry-check" aria-label="Permalink to &quot;6. Non-Dataflow Checks (`LearnedFactEntry::Check`)&quot;">​</a></h3><p>Direct code structure inspection that does not require tracking variable flows.</p><ul><li><strong>What is taught</strong>: Detecting calls to deprecated APIs or configuration functions missing mandatory flags.</li></ul><h3 id="_7-memory-contracts-learnedfactentry-memorycontract" tabindex="-1">7. Memory Contracts (<code>LearnedFactEntry::MemoryContract</code>) <a class="header-anchor" href="#_7-memory-contracts-learnedfactentry-memorycontract" aria-label="Permalink to &quot;7. Memory Contracts (`LearnedFactEntry::MemoryContract`)&quot;">​</a></h3><p>Tracks heap allocation and deallocation across boundaries in systems languages (C, C++, Rust).</p><ul><li><strong>What is taught</strong>: Which functions allocate new memory and which functions consume/free pointers, preventing use-after-free bugs.</li></ul><h3 id="_8-cryptographic-standards-learnedfactentry-weakcrypto" tabindex="-1">8. Cryptographic Standards (<code>LearnedFactEntry::WeakCrypto</code>) <a class="header-anchor" href="#_8-cryptographic-standards-learnedfactentry-weakcrypto" aria-label="Permalink to &quot;8. Cryptographic Standards (`LearnedFactEntry::WeakCrypto`)&quot;">​</a></h3><p>Enforces corporate cryptography standards.</p><ul><li><strong>What is taught</strong>: Flagging weak hash algorithms (<code>md5</code>, <code>sha1</code>, <code>des</code>) while allowing secure algorithms (<code>sha256</code>, <code>argon2id</code>).</li></ul><h3 id="_9-authorization-guards-learnedfactentry-guardbypass" tabindex="-1">9. Authorization Guards (<code>LearnedFactEntry::GuardBypass</code>) <a class="header-anchor" href="#_9-authorization-guards-learnedfactentry-guardbypass" aria-label="Permalink to &quot;9. Authorization Guards (`LearnedFactEntry::GuardBypass`)&quot;">​</a></h3><p>Recognizes authorization and containment checks.</p><ul><li><strong>What is taught</strong>: Helper functions that validate whether a requested resource belongs to the current user or tenant.</li></ul><h3 id="_10-schema-validation-learnedfactentry-schemapolicy" tabindex="-1">10. Schema Validation (<code>LearnedFactEntry::SchemaPolicy</code>) <a class="header-anchor" href="#_10-schema-validation-learnedfactentry-schemapolicy" aria-label="Permalink to &quot;10. Schema Validation (`LearnedFactEntry::SchemaPolicy`)&quot;">​</a></h3><p>Recognizes input validation frameworks (such as Zod, Yup, or Pydantic).</p><ul><li><strong>What is taught</strong>: Acknowledging that data passing through schema validator methods is validated.</li></ul><h3 id="_11-syntax-roles-learnedfactentry-grammarrole" tabindex="-1">11. Syntax Roles (<code>LearnedFactEntry::GrammarRole</code>) <a class="header-anchor" href="#_11-syntax-roles-learnedfactentry-grammarrole" aria-label="Permalink to &quot;11. Syntax Roles (`LearnedFactEntry::GrammarRole`)&quot;">​</a></h3><p>Teaches the parser how new or unusual language syntax functions without modifying the engine.</p><ul><li><strong>What is taught</strong>: Mapping language AST nodes to functions, variables, or call expressions dynamically.</li></ul><h3 id="_12-syntax-features-learnedfactentry-grammarfeature" tabindex="-1">12. Syntax Features (<code>LearnedFactEntry::GrammarFeature</code>) <a class="header-anchor" href="#_12-syntax-features-learnedfactentry-grammarfeature" aria-label="Permalink to &quot;12. Syntax Features (`LearnedFactEntry::GrammarFeature`)&quot;">​</a></h3><p>Teaches language idioms like object destructuring, template literals, and ternary operators.</p><ul><li><strong>What is taught</strong>: Enabling accurate variable tracking through modern JavaScript or Python language features.</li></ul><h3 id="_13-access-control-multi-tenancy-learnedfactentry-idorfindersink" tabindex="-1">13. Access Control &amp; Multi-Tenancy (<code>LearnedFactEntry::IdorFinderSink</code>) <a class="header-anchor" href="#_13-access-control-multi-tenancy-learnedfactentry-idorfindersink" aria-label="Permalink to &quot;13. Access Control &amp; Multi-Tenancy (`LearnedFactEntry::IdorFinderSink`)&quot;">​</a></h3><p>Detects Insecure Direct Object References (IDOR).</p><ul><li><strong>What is taught</strong>: Database query methods and required multi-tenant ownership keys (e.g., <code>account_id</code>, <code>tenant_id</code>).</li></ul><hr><h2 id="step-by-step-how-to-teach-frensense-in-practice" tabindex="-1">Step-by-Step: How to Teach Frensense in Practice <a class="header-anchor" href="#step-by-step-how-to-teach-frensense-in-practice" aria-label="Permalink to &quot;Step-by-Step: How to Teach Frensense in Practice&quot;">​</a></h2><h3 id="step-1-create-a-corpus-folder" tabindex="-1">Step 1: Create a Corpus Folder <a class="header-anchor" href="#step-1-create-a-corpus-folder" aria-label="Permalink to &quot;Step 1: Create a Corpus Folder&quot;">​</a></h3><p>Create a directory with positive and negative code snippets:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_corpus/custom_auth</span></span></code></pre></div><p>Create <code>custom_auth_positive.py</code> (the bug):</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># VULNERABLE: Direct lookup without tenant scoping</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> get_invoice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(req):</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    invoice_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> req.args.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.query_invoice(invoice_id)</span></span></code></pre></div><p>Create <code>custom_auth_negative.py</code> (the fix):</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SAFE: Scoped lookup requiring active organization ID</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> get_invoice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(req):</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    invoice_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> req.args.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    org_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> req.session.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.query_invoice(invoice_id, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">org_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">org_id)</span></span></code></pre></div><h3 id="step-2-build-the-bundle" tabindex="-1">Step 2: Build the Bundle <a class="header-anchor" href="#step-2-build-the-bundle" aria-label="Permalink to &quot;Step 2: Build the Bundle&quot;">​</a></h3><p>Run the Frensense bundler tool:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense-bundler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_corpus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_company.frc</span></span></code></pre></div><p>The bundler extracts the fact, executes the <strong>replay verification gate</strong> across both files, and outputs a binary <code>my_company.frc</code> knowledge bundle.</p><h3 id="step-3-scan-with-your-knowledge-bundle" tabindex="-1">Step 3: Scan with Your Knowledge Bundle <a class="header-anchor" href="#step-3-scan-with-your-knowledge-bundle" aria-label="Permalink to &quot;Step 3: Scan with Your Knowledge Bundle&quot;">​</a></h3><p>Provide the bundle to the scanner:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --corpus-bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_company.frc</span></span></code></pre></div><p>Or drop <code>frensense-corpus.frc</code> directly into the root directory of your project; Frensense will discover and load it automatically.</p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="do-i-need-to-know-rust-to-teach-frensense" tabindex="-1">Do I need to know Rust to teach Frensense? <a class="header-anchor" href="#do-i-need-to-know-rust-to-teach-frensense" aria-label="Permalink to &quot;Do I need to know Rust to teach Frensense?&quot;">​</a></h3><p><strong>No.</strong> All training examples are written in the target language of your application (Python, TypeScript, JavaScript, Go, C, Rust). The bundler handles all analysis and translation into binary knowledge bundles.</p><h3 id="what-happens-if-a-learned-rule-conflicts-with-built-in-rules" tabindex="-1">What happens if a learned rule conflicts with built-in rules? <a class="header-anchor" href="#what-happens-if-a-learned-rule-conflicts-with-built-in-rules" aria-label="Permalink to &quot;What happens if a learned rule conflicts with built-in rules?&quot;">​</a></h3><p>Knowledge bundles are designed with safe precedence:</p><ul><li><strong>Learned facts win on specific knowledge</strong>: If a bundle teaches that a specific parameter is safe, that precision overrides generic defaults.</li><li><strong>Narrow facts cannot be widened</strong>: A generic rule cannot overwrite a precise, slot-restricted signature.</li></ul><h3 id="how-does-frensense-prevent-false-alarms-from-learned-rules" tabindex="-1">How does Frensense prevent false alarms from learned rules? <a class="header-anchor" href="#how-does-frensense-prevent-false-alarms-from-learned-rules" aria-label="Permalink to &quot;How does Frensense prevent false alarms from learned rules?&quot;">​</a></h3><p>Before any rule is written into an <code>.frc</code> bundle, it must pass the <strong>Replay Gate</strong>. The candidate rule is tested against all negative examples in the corpus. If it causes even a single false positive on safe code, the bundler rejects it.</p>',82)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
